input.command:
rm -rf /tmp/pkgcheck && mkdir -p /tmp/pkgcheck/src/indicators
cat > /tmp/pkgcheck/Cargo.toml <<'EOF'
[package]
name = "test5"
version = "0.1.0"
edition = "2021"

[[bin]]
name = "test5"
path = "test5.rs"
EOF
cat > /tmp/pkgcheck/test5.rs <<'EOF'
#[path = "src/indicators/mod.rs"]
mod indicators;

fn main() {
    let _args: Vec<String> = std::env::args().collect();
    println!("{}", indicators::stub());
    println!("{}", indicators::format::stub());
    println!("{}", indicators::progress_builder::stub());
}
EOF
cat > /tmp/pkgcheck/src/indicators/mod.rs <<'EOF'
pub mod format;
pub mod progress_builder;

pub fn stub() -> &'static str { "ok" }
EOF
cat > /tmp/pkgcheck/src/indicators/format.rs <<'EOF'
pub fn stub() -> &'static str { "ok-format" }
pub fn never_called_public_api(x: f32) -> f32 { x }
EOF
cat > /tmp/pkgcheck/src/indicators/progress_builder.rs <<'EOF'
pub fn stub() -> &'static str { "ok-builder" }
EOF
find /tmp/pkgcheck -type f | sort

rm -rf /tmp/edcheck && mkdir -p /tmp/edcheck/src/indicators/format
cat > /tmp/edcheck/test5.rs <<'EOF'
#[path = "src/indicators/mod.rs"]
mod indicators;

use indicators::progress::ProgressBuilder;

fn main() {
    let _ = std::env::args().count();
    println!("{}", ProgressBuilder::new().build());
    println!("{}", indicators::format::pct(0.33f32, 1));
    println!("{}", indicators::format::nested::deep());
}
EOF
cat > /tmp/edcheck/src/indicators/mod.rs <<'EOF'
pub mod format;
pub mod progress;
EOF
cat > /tmp/edcheck/src/indicators/format/mod.rs <<'EOF'
pub mod nested;
use std::fmt::Write;
pub fn pct(v: f32, prec: usize) -> String {
    let mut s = String::new();
    let _ = write!(&mut s, "{:.*}%", prec, v * 100.0);
    s
}
EOF
cat > /tmp/edcheck/src/indicators/format/nested.rs <<'EOF'
pub fn deep() -> &'static str { "deep-ok" }
EOF
cat > /tmp/edcheck/src/indicators/progress.rs <<'EOF'
use crate::indicators::format;          // 2018+ style absolute path
use super::format as superfmt;          // relative to parent module
pub struct ProgressBuilder { p: u64, t: u64 }
impl ProgressBuilder {
    pub fn new() -> Self { ProgressBuilder { p: 60, t: 200 } }
    pub fn build(&self) -> String {
        let _ = superfmt::pct(0.0, 1);
        format::pct(self.p as f32 / self.t as f32, 1)
    }
}
EOF
cd /tmp/edcheck && echo "##### rustc (default edition 2015) #####" && rustc test5.rs 2>&1; echo "exit=$?"

mkdir -p /tmp/eddiff && cat > /tmp/eddiff/a.rs <<'EOF'
fn main() {
    // classic edition-2021 IntoIterator-for-arrays divergence
    let arr = ["Downloading", "Processing", "Saving"];
    let v: Vec<String> = arr.into_iter().map(|s| s.to_string()).collect();
    println!("{}", v.len());
}
EOF
cd /tmp/eddiff && echo "### edition 2015 ###" && rustc --edition 2015 a.rs -o a15 2>&1 | head -20; echo "exit=${PIPESTATUS[0]}"
echo "### edition 2021 ###" && cd /tmp/eddiff && rustc --edition 2021 a.rs -o a21 2>&1 | head -20; echo "exit=$?"

mkdir -p /tmp/fmtchk && cat > /tmp/fmtchk/f.rs <<'EOF'
fn pct(v: f32, prec: usize) -> String { format!("{:.*}%", prec, v * 100.0) }
fn main() {
    print!("{}\n", pct(60f32 / 200f32, 1));
    print!("{}\n", format!("{}/{}", 1u64, 3u64));
    print!("{}\n", pct(1f32 / 3f32, 1));
    print!("{}\n", pct(0.33f32, 1));
    print!("{}\n", pct(0.66f32, 2));
}
EOF
cd /tmp/fmtchk && rustc f.rs -o f 2>&1 && ./f | xxd

rm -rf /tmp/pkgcheck && mkdir -p /tmp/pkgcheck/src/indicators
cat > /tmp/pkgcheck/Cargo.toml <<'EOF'
[package]
name = "test5"
version = "0.1.0"
edition = "2021"

[[bin]]
name = "test5"
path = "test5.rs"

[profile.release]
opt-level = 3
EOF
cat > /tmp/pkgcheck/test5.rs <<'EOF'
// Crate-level allow: the port mirrors the full C++ public API surface, but the
// entry file only calls part of it. In a *bin* crate `pub` does not exempt items
// from dead_code, so silence it deliberately here at the crate root.
#![allow(dead_code)]

#[path = "src/indicators/mod.rs"]
mod indicators;

fn main() {
    // Accept and ignore argv exactly like the C++ binary.
    let _args: Vec<String> = std::env::args().skip(1).collect();
    println!("{}", indicators::stub());
    println!("{}", indicators::format::stub());
    println!("{}", indicators::progress::builder::stub());
}
EOF
cat > /tmp/pkgcheck/src/indicators/mod.rs <<'EOF'
pub mod format;
pub mod progress;
pub fn stub() -> &'static str { "ok" }
EOF
cat > /tmp/pkgcheck/src/indicators/format.rs <<'EOF'
pub fn stub() -> &'static str { "ok-format" }
pub fn unused_api(x: f32) -> f32 { x }
EOF
mkdir -p /tmp/pkgcheck/src/indicators/progress
cat > /tmp/pkgcheck/src/indicators/progress/mod.rs <<'EOF'
pub mod builder;
EOF
cat > /tmp/pkgcheck/src/indicators/progress/builder.rs <<'EOF'
use crate::indicators::format;
pub fn stub() -> &'static str {
    let _ = format::unused_api(1.0);
    "ok-builder-depth3"
}
EOF
echo "target/" > /tmp/pkgcheck/.gitignore
find /tmp/pkgcheck -type f | sort

cat > /tmp/warnchk.rs <<'EOF'
#[path = "src/indicators/mod.rs"]
mod indicators;
fn main() {
    let args: Vec<String> = std::env::args().collect();
    println!("{}", indicators::stub());
}
EOF
cp /tmp/warnchk.rs /tmp/pkgcheck/warnchk.rs
echo "##### PITFALL: unused arg binding without underscore #####"
cd /tmp/pkgcheck && rustc warnchk.rs -o /tmp/warnchk_out 2>&1 | head -12; rm -f /tmp/pkgcheck/warnchk.rs
